import{c as a,U as r,j as i,g as s,o as n,a6 as l,n as o}from"./chunks/framework.h4W4t1IS.js";const b=JSON.parse('{"title":"UML - Modélisation des classes et des objets","description":"","frontmatter":{"title":"UML - Modélisation des classes et des objets","status":"ready","tags":["uml","all"],"authors":["Jean-François Dion"],"reviewers":[]},"headers":[],"relativePath":"uml/uml.md","filePath":"uml/uml.md"}'),u={name:"uml/uml.md"},d={id:"frontmatter-title",tabindex:"-1"};function m(t,e,c,p,g,h){return r(),i("div",null,[s("h1",d,[n(l(t.$frontmatter.title)+" ",1),e[0]||(e[0]=s("a",{class:"header-anchor",href:"#frontmatter-title","aria-label":'Permalink to "{{ $frontmatter.title }}"'},"​",-1))]),e[1]||(e[1]=o('<p>La modélisation <a href="/420-w30-sf-po2/lexique.html#uml" class="lexicon-link" title="Langage de modélisation graphique pour représenter les systèmes logiciels, incluant des diagrammes de classes, de séquence, d&#39;activités et d&#39;états.">UML</a> n&#39;a plus la place qu&#39;elle a déjà eue dans le développement de systèmes, mais demeure tout de même un outil de communication indispensable pour les développeurs. Elle permet de représenter visuellement la structure d&#39;un système et les relations entre ses classes, facilitant la compréhension et la communication au sein d&#39;une équipe.</p><h2 id="objectifs-d-apprentissage" tabindex="-1">Objectifs d&#39;apprentissage <a class="header-anchor" href="#objectifs-d-apprentissage" aria-label="Permalink to &quot;Objectifs d&#39;apprentissage&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Après cette section, tu seras capable de...</p><ul><li>Expliquer l&#39;utilité des diagrammes UML</li><li>Distinguer les diagrammes structurels des diagrammes comportementaux</li><li>Situer le diagramme de classes parmi les autres diagrammes UML</li></ul></div><h2 id="qu-est-ce-qu-uml" tabindex="-1">Qu&#39;est-ce qu&#39;UML <a class="header-anchor" href="#qu-est-ce-qu-uml" aria-label="Permalink to &quot;Qu&#39;est-ce qu&#39;UML&quot;">​</a></h2><p><strong>UML</strong> (<em>Unified Modeling Language</em>) est un langage de modélisation graphique normalisé (par l&#39;OMG — <em>Object Management Group</em>) permettant de représenter la structure et le comportement d&#39;un système orienté objet, indépendamment du langage de programmation utilisé.</p><p>UML n&#39;est pas une méthodologie ni un processus : c&#39;est un vocabulaire visuel commun. Deux développeurs qui ne partagent aucun code peuvent tout de même se comprendre en dessinant le même diagramme, parce que la notation est standardisée.</p><h2 id="pourquoi-utiliser-uml" tabindex="-1">Pourquoi utiliser UML <a class="header-anchor" href="#pourquoi-utiliser-uml" aria-label="Permalink to &quot;Pourquoi utiliser UML&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Quand UML est utile</p><p>UML est un outil de communication, pas une fin en soi. Il vaut la peine d&#39;être utilisé quand il <strong>clarifie</strong> une conception — pas pour documenter chaque classe du système dans l&#39;exhaustivité.</p></div><ul><li><strong>Concevoir avant de coder</strong> : esquisser la structure d&#39;un système (classes, relations) avant d&#39;écrire du code aide à repérer les problèmes de conception tôt, quand ils coûtent le moins cher à corriger.</li><li><strong>Communiquer une conception</strong> : un diagramme partagé en <a href="/420-w30-sf-po2/lexique.html#revue-de-code" class="lexicon-link" title="Examen du code d&#39;un pair avant intégration : lire les tests d&#39;abord, vérifier les conventions et les principes SOLID, commenter précisément et de façon constructive.">revue de code</a> ou en réunion d&#39;équipe transmet une structure plus rapidement qu&#39;une description textuelle ou qu&#39;une lecture ligne par ligne du code.</li><li><strong>Documenter un système existant</strong> : un diagramme de classes généré ou dessiné à partir du code aide un nouveau membre de l&#39;équipe à se familiariser avec une base de code sans devoir la parcourir en entier.</li></ul><h2 id="les-types-de-diagrammes-uml" tabindex="-1">Les types de diagrammes UML <a class="header-anchor" href="#les-types-de-diagrammes-uml" aria-label="Permalink to &quot;Les types de diagrammes UML&quot;">​</a></h2><p>UML définit une quinzaine de types de diagrammes, regroupés en deux grandes catégories.</p><h3 id="diagrammes-structurels" tabindex="-1">Diagrammes structurels <a class="header-anchor" href="#diagrammes-structurels" aria-label="Permalink to &quot;Diagrammes structurels&quot;">​</a></h3><p>Représentent l&#39;organisation statique d&#39;un système : ses classes, objets, composants et leurs relations. Le plus utilisé est le <strong>diagramme de classes</strong>, sujet des sections suivantes.</p><p>D&#39;autres diagrammes structurels existent (diagramme d&#39;objets, de composants, de déploiement, de paquetages), mais sont peu utilisés en dehors de contextes d&#39;architecture logicielle plus larges.</p><h3 id="diagrammes-comportementaux" tabindex="-1">Diagrammes comportementaux <a class="header-anchor" href="#diagrammes-comportementaux" aria-label="Permalink to &quot;Diagrammes comportementaux&quot;">​</a></h3><p>Représentent la dynamique d&#39;un système : les interactions entre objets et l&#39;évolution des états dans le temps. Par exemple :</p><ul><li><strong>Diagramme de séquence</strong> : illustre l&#39;ordre des appels entre objets pour réaliser un scénario précis</li><li><strong>Diagramme d&#39;états</strong> : illustre les états possibles d&#39;un objet et les transitions entre eux</li><li><strong>Diagramme de cas d&#39;utilisation</strong> : illustre les interactions entre les utilisateurs (acteurs) et le système</li></ul><p>Ce cours se concentre sur le <strong>diagramme de classes</strong>, le plus fondamental pour représenter la conception orientée objet d&#39;un système.</p>',18))])}const f=a(u,[["render",m]]);export{b as __pageData,f as default};
